import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"BOOM","description":"","frontmatter":{"title":"BOOM"},"headers":[],"relativePath":"general/boom.md","filePath":"general/boom.md","lastUpdated":null}'),o={name:"general/boom.md"};function n(s,e,l,d,u,c){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="boom" tabindex="-1">BOOM <a class="header-anchor" href="#boom" aria-label="Permalink to &quot;BOOM&quot;">​</a></h1><ol><li>sUAS Munitions and Explosives This page details the types, configurations, and effects of munitions and explosives integrated with small Unmanned Aerial Systems (sUAS), with a focus on improvised and semi-formal systems used in the Russo-Ukrainian war from 2022–2025. It includes insights from official military frameworks and OSINT analysis.</li></ol><p><a href="https://u.pcloud.link/publink/show?code=XZTh2j5ZOzmvlUSIbLYQbwrTyWEyKRl2abPX" target="_blank" rel="noreferrer">&quot;EXPLOSIVE DEVICES FOR UNPILOTED LETHAL VEHICLES&quot;</a> contains a lot of information on the types of explosives and munitions used in sUAS in the right against Russia by Ukrainian Forces.</p><h3 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms&quot;">​</a></h3><ul><li><p><strong>ESAD</strong>: Electronic Safe and Arm Device — Controls firing sequence electronically with safety interlocks.</p></li><li><p><strong>ESAF</strong>: Electronic Safe Arm and Fire — Legacy British term, interchangeable with ESAD in most contexts.</p></li><li><p><strong>HME</strong>: Homemade Explosives — Any non-commercial explosive synthesized from precursors, typically for DIY or non-state applications.</p></li><li><p><strong>COTS</strong>: Commercial Off The Shelf — Readily available, mass-market components, often repurposed for military use.</p></li><li><p><strong>F&amp;DR</strong>: Fielding and Deployment Release — A formal approval for military use of a system or munition.</p></li><li><p><strong>DEVCOM Audible</strong>: A U.S. Army-developed dropper platform enabling safe release of Army-issued munitions via sUAS.</p></li></ul><h3 id="munition-types-used-in-suas" tabindex="-1">Munition Types Used in sUAS <a class="header-anchor" href="#munition-types-used-in-suas" aria-label="Permalink to &quot;Munition Types Used in sUAS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Munition Type</th><th>Description</th><th>Common Deployment</th><th>Observed Effects</th></tr></thead><tbody><tr><td>PG-7V warhead</td><td>Rocket-propelled grenade (shaped charge, anti-armor/HEAT)</td><td>FPV drone front-load</td><td>Armor penetration, structural destruction. See <a href="https://web.archive.org/web/20250605032724/https://en.wikipedia.org/wiki/RPG-7" target="_blank" rel="noreferrer">RPG-7 archive</a></td></tr><tr><td>OG-7 warhead</td><td>Rocket-propelled grenade (fragmentation, anti-personnel)</td><td>FPV drone front-load</td><td>Wide-area blast and fragmentation, highly lethal to exposed personnel</td></tr><tr><td>VOG-17 / VOG-25</td><td>40 mm grenade (airburst/impact)</td><td>Servo-drop mod or breakaway mount</td><td>Infantry suppression, light vehicle disablement</td></tr><tr><td>RGO / RGN</td><td>Soviet defensive hand grenades</td><td>Drop with fuse-delay</td><td>Fragmentation anti-personnel</td></tr><tr><td>Thermite canister</td><td>Thermite mix in metal container</td><td>Drop or crash delivery</td><td>Incendiary burn-through (fuel tanks, radomes)</td></tr><tr><td>C4 / Semtex block</td><td>Commercial/military plastic explosive</td><td>Crash-load in kamikaze drones</td><td>Focused blast, breaching</td></tr><tr><td>HME charges</td><td>AN mixtures, NM-based, poor-man&#39;s C4</td><td>Custom DIY FPV builds</td><td>Mixed reliability; cost-effective</td></tr><tr><td>Improvised shaped charge</td><td>Metal cone with explosive liner</td><td>Nose-mounted kamikaze</td><td>Penetrative focused effect</td></tr></tbody></table><h3 id="example-payload-configurations" tabindex="-1">Example Payload Configurations <a class="header-anchor" href="#example-payload-configurations" aria-label="Permalink to &quot;Example Payload Configurations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Drone Type</th><th>Frame/Style</th><th>Munition</th><th>Trigger System</th></tr></thead><tbody><tr><td>FPV Kamikaze</td><td>5–7&quot; carbon X-frame</td><td>PG-7V / VOG-25</td><td>MOSFET + dual-pin ESAD</td></tr><tr><td>Servo-drop DJI</td><td>DJI Mavic 3 + dropper</td><td>RGO / VOG</td><td>Servo + timer / RC switch</td></tr><tr><td>Stick drone</td><td>Wood-arm DIY</td><td>Thermite / HME</td><td>Contact or timed impact</td></tr><tr><td>Hybrid VTOL</td><td>Fixed-wing / quad</td><td>VOG bundle</td><td>Servo dropper + GPS waypoint</td></tr></tbody></table><h3 id="notable-use-cases" tabindex="-1">Notable Use Cases <a class="header-anchor" href="#notable-use-cases" aria-label="Permalink to &quot;Notable Use Cases&quot;">​</a></h3><h3 id="june-2025-–-strategic-bomber-airbase-attacks" tabindex="-1">June 2025 – Strategic Bomber Airbase Attacks <a class="header-anchor" href="#june-2025-–-strategic-bomber-airbase-attacks" aria-label="Permalink to &quot;June 2025 – Strategic Bomber Airbase Attacks&quot;">​</a></h3><ul><li><p><strong>Target</strong>: Engels and Soltsy-2 airbases (Tu-95, Tu-160 bombers).</p></li><li><p><strong>Tactics</strong>: Long-range DIY drones (&gt;600 km) using internal fuel bladders, carrying ~3 kg thermobaric or HME payloads.</p></li><li><p><strong>Effects</strong>: Confirmed airframe damage and runway disruption. Satellite imagery showed heat signatures and repair activity within 24 hours.</p></li><li><p><strong>Payloads</strong>: Believed to include ANFO or nitromethane-based charges. Use of low-metal signature airframes suggested radar evasion.</p></li></ul><h3 id="_2023–2024-evolution-of-diy-fpv-attacks" tabindex="-1">2023–2024: Evolution of DIY FPV Attacks <a class="header-anchor" href="#_2023–2024-evolution-of-diy-fpv-attacks" aria-label="Permalink to &quot;2023–2024: Evolution of DIY FPV Attacks&quot;">​</a></h3><ul><li><p><strong>Initial stage</strong>: 3D-printed nosecones for VOG-17s, dropped manually.</p></li><li><p><strong>Improved stage</strong>: Hardened nose for PG-7 warheads, with dual-signal arming logic to prevent premature detonation.</p></li><li><p><strong>Safety upgrades</strong>: Widespread adoption of ESAD-style boards in fielded FPV units. Dual-command MOSFET logic became a standard.</p></li></ul><h3 id="safety-and-regulatory-considerations" tabindex="-1">Safety and Regulatory Considerations <a class="header-anchor" href="#safety-and-regulatory-considerations" aria-label="Permalink to &quot;Safety and Regulatory Considerations&quot;">​</a></h3><h3 id="u-s-army-and-dod-standards" tabindex="-1">U.S. Army and DoD Standards <a class="header-anchor" href="#u-s-army-and-dod-standards" aria-label="Permalink to &quot;U.S. Army and DoD Standards&quot;">​</a></h3><ul><li><p>Any modified munition or new delivery configuration requires an F&amp;DR before deployment.</p></li><li><p>Safety testing must validate:</p><ul><li>Arming delay</li><li>Flight stability</li><li>Fail-safe logic</li><li>Blast radius modeling</li></ul></li></ul><h3 id="civilian-context-u-s-regulations" tabindex="-1">Civilian Context (U.S. Regulations) <a class="header-anchor" href="#civilian-context-u-s-regulations" aria-label="Permalink to &quot;Civilian Context (U.S. Regulations)&quot;">​</a></h3><ul><li>Manufacture of explosives (including HMEs) is <strong>legal</strong> only when: <ul><li>Not stored or transported commercially</li><li>Not intended for criminal or commercial use</li><li>Made in compliance with ATF regs and away from public areas</li></ul></li></ul><h3 id="informal-practices-field-level" tabindex="-1">Informal Practices (Field-Level) <a class="header-anchor" href="#informal-practices-field-level" aria-label="Permalink to &quot;Informal Practices (Field-Level)&quot;">​</a></h3><ul><li>Safety SOPs often include: <ul><li>Always use dual-arm logic (RC + mechanical)</li><li>Avoid nitrile gloves when working with nitric acid mixes</li><li>Store separated precursors, not pre-mixed charges</li><li>Minimize metal in airframe to reduce radar signature</li></ul></li></ul><h3 id="trends-in-improvised-munitions" tabindex="-1">Trends in Improvised Munitions <a class="header-anchor" href="#trends-in-improvised-munitions" aria-label="Permalink to &quot;Trends in Improvised Munitions&quot;">​</a></h3><ul><li><p><strong>AN mixtures</strong>: Low-cost, easy-to-source, high-yield.</p></li><li><p><strong>Nitromethane blends</strong>: Enhanced detonation velocity, used in combo with shrapnel canisters.</p></li><li><p><strong>Poor-man&#39;s C4</strong>: Often ETN or PETN-based, cast into putty with plasticizers.</p></li><li><p><strong>Thermite</strong>: Reliable for damaging engine blocks and electronics.</p></li></ul><h3 id="field-observations" tabindex="-1">Field Observations <a class="header-anchor" href="#field-observations" aria-label="Permalink to &quot;Field Observations&quot;">​</a></h3><ul><li><p>Thermal imagery shows kamikaze FPV drones deliver a downward-blast profile — suggesting shaped or contact charges.</p></li><li><p>Ukrainian units have adopted modular payload rails, enabling plug-and-play bomb modules on the same drone chassis.</p></li><li><p>Remote ESAD triggering via FC spare UART channels becoming standard for trained units.</p></li></ul><h3 id="future-considerations" tabindex="-1">Future Considerations <a class="header-anchor" href="#future-considerations" aria-label="Permalink to &quot;Future Considerations&quot;">​</a></h3><ul><li><p>Formalization of DIY bomb-droppers via DEVCOM Audible platform could accelerate standardization.</p></li><li><p>NATO-aligned safety certification may be introduced for partner-state UAS payloads.</p></li><li><p>OSINT tracking of explosive effectiveness could inform future modular UAS ordinance kits.</p></li></ul><h3 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h3><ul><li><p>[* <a href="/general/suas.html">https://www.youtube.com/@duganashley1337 duganashley1337 youtube playlist</a></p></li><li><p><a href="https://drive.google.com/drive/folders/0B8YTArDdXJ6eYUs4Zzc0NW5hY3c?resourcekey=0-MhNPSYLgtFHG1dMiSY4pyw" target="_blank" rel="noreferrer">Home Made Explosive Literature</a></p></li></ul><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>[Required]</p><p>[Weapons]</p>',32)])])}const h=t(o,[["render",n]]);export{p as __pageData,h as default};
